// ChartDb.m — 内置谱面查询用的曲库（源自 lxns 曲库，deflate + base64 嵌在二进制里）
// 生成方式见 tools/build_chartdb.py；不要手改下面的数据段。
#import "ChartDb.h"
#import <zlib.h>
#import <string.h>

// 压缩后的 JSON：{"g":[分类...],"s":[[id,曲名,艺术家,分类下标,BPM,版本,发布年,[别名],[标准谱面],[DX谱面]],...]}
// 谱面 = [难度 0-4, 定数, 谱师]
static NSString * const kChartDbB64 =
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @"";


static NSDictionary *gDb = nil;

// 曲目数组的字段下标
enum {
    ADXSongId = 0,      // int，基础号（DX 曲的显示号 = 10000 + id）
    ADXSongTitle,       // 曲名
    ADXSongArtist,      // 艺术家
    ADXSongGenre,       // 分类下标 → db[@"g"]
    ADXSongBpm,         // BPM
    ADXSongVersion,     // 版本码，如 24004
    ADXSongYear,        // 发布年份
    ADXSongAliases,     // [别名]
    ADXSongStd,         // [[难度, 定数, 谱师], ...]
    ADXSongDx           // 同上，DX 谱面
};

@implementation ADXChartDb

+ (NSData *)inflate:(NSData *)data
{
    if (data.length < 2) return nil;

    z_stream zs;
    memset(&zs, 0, sizeof(zs));
    if (inflateInit2(&zs, -15) != Z_OK) return nil;

    NSMutableData *out = [NSMutableData dataWithCapacity:data.length * 4];
    uint8_t buf[65536];
    zs.next_in = (Bytef *)data.bytes;
    zs.avail_in = (uInt)data.length;

    int ret = Z_OK;
    while (ret != Z_STREAM_END) {
        zs.next_out = buf;
        zs.avail_out = sizeof(buf);
        ret = inflate(&zs, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) break;
        [out appendBytes:buf length:sizeof(buf) - zs.avail_out];
        if (zs.avail_in == 0 && ret != Z_STREAM_END) break;
    }
    inflateEnd(&zs);
    return (ret == Z_STREAM_END) ? out : nil;
}

+ (NSDictionary *)db
{
    if (gDb) return gDb;

    NSData *packed = [[NSData alloc] initWithBase64EncodedString:kChartDbB64 options:0];
    NSData *json = packed ? [self inflate:packed] : nil;
    id obj = json ? [NSJSONSerialization JSONObjectWithData:json options:0 error:nil] : nil;
    if ([obj isKindOfClass:[NSDictionary class]]) {
        gDb = obj;
    } else {
        gDb = @{ @"g": @[], @"s": @[] };
    }
    return gDb;
}

+ (NSArray *)songs
{
    NSArray *s = [self db][@"s"];
    return [s isKindOfClass:[NSArray class]] ? s : @[];
}

+ (NSArray *)search:(NSString *)keyword limit:(NSUInteger)limit
{
    NSString *q = [keyword stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (!q.length) return @[];

    NSArray *songs = [self songs];

    // 纯数字：按编号找，同时接受基础号和 DX 号（11391 与 1391 都能搜到 WIPE OUT MEMORIES）
    BOOL numeric = YES;
    for (NSUInteger i = 0; i < q.length; i++) {
        unichar c = [q characterAtIndex:i];
        if (c < '0' || c > '9') { numeric = NO; break; }
    }

    if (numeric) {
        long long n = q.longLongValue;
        NSMutableArray *hits = [NSMutableArray array];
        for (NSArray *s in songs) {
            if (s.count <= ADXSongDx) continue;
            long long sid = [s[ADXSongId] longLongValue];
            if (sid == n || (n >= 10000 && sid == n - 10000)) [hits addObject:s];
        }
        if (limit && hits.count > limit) return [hits subarrayWithRange:NSMakeRange(0, limit)];
        return hits;
    }

    NSString *lower = q.lowercaseString;
    NSMutableArray *prefixed = [NSMutableArray array];
    NSMutableArray *other = [NSMutableArray array];

    for (NSArray *s in songs) {
        if (s.count <= ADXSongDx) continue;
        NSString *title = s[ADXSongTitle];
        if (![title isKindOfClass:[NSString class]]) continue;
        NSString *tl = title.lowercaseString;

        BOOL hit = ([tl rangeOfString:lower].location != NSNotFound);
        if (!hit) {
            id artist = s[ADXSongArtist];
            if ([artist isKindOfClass:[NSString class]])
                hit = ([artist.lowercaseString rangeOfString:lower].location != NSNotFound);
        }
        if (!hit) {
            for (NSString *a in s[ADXSongAliases]) {
                if (![a isKindOfClass:[NSString class]]) continue;
                if ([a.lowercaseString rangeOfString:lower].location != NSNotFound) { hit = YES; break; }
            }
        }
        if (!hit) continue;

        if ([tl hasPrefix:lower]) [prefixed addObject:s];
        else [other addObject:s];
    }

    NSMutableArray *out = [NSMutableArray arrayWithCapacity:prefixed.count + other.count];
    [out addObjectsFromArray:prefixed];
    [out addObjectsFromArray:other];
    if (limit && out.count > limit) return [out subarrayWithRange:NSMakeRange(0, limit)];
    return out;
}

+ (BOOL)hasDx:(NSArray *)song
{
    NSArray *dx = song[ADXSongDx];
    return [dx isKindOfClass:[NSArray class]] && dx.count > 0;
}

/// 玩家习惯的编号：有 DX 谱面时用 10000 + 基础号
+ (int)displayId:(NSArray *)song
{
    int sid = [song[ADXSongId] intValue];
    return [self hasDx:song] ? sid + 10000 : sid;
}

+ (NSString *)genreName:(NSArray *)song
{
    NSArray *g = [self db][@"g"];
    NSInteger i = [song[ADXSongGenre] integerValue];
    if (i >= 0 && i < (NSInteger)g.count) return g[i];
    return @"";
}

+ (NSString *)versionName:(NSArray *)song
{
    static int codes[] = {19900, 19500, 19000, 18500, 18000, 17000, 16000, 15000, 14000, 13000, 12000, 11000, 10000};
    static NSString *names[] = {
        @"舞萌 FiNALE", @"舞萌 MiLK PLUS", @"舞萌 MiLK",
        @"舞萌 MURASAKi PLUS", @"舞萌 MURASAKi",
        @"舞萌 PiNK PLUS", @"舞萌 PiNK",
        @"舞萌 ORANGE PLUS", @"舞萌 ORANGE",
        @"舞萌 GreeN PLUS", @"舞萌 GreeN",
        @"舞萌 PLUS", @"舞萌"
    };

    int v = [song[ADXSongVersion] intValue];
    if (v >= 20000) {
        int y = MAX(2020, [song[ADXSongYear] intValue]);
        if (y <= 2020) return @"舞萌DX";
        return [NSString stringWithFormat:@"舞萌DX %d", y];
    }
    for (int i = 0; i < 13; i++)
        if (v >= codes[i]) return names[i];
    return @"舞萌";
}

/// 详情页用：把某一边（标准 / DX）的谱面按难度从高到低排好
+ (NSArray *)chartsOf:(NSArray *)song dx:(BOOL)dx
{
    NSArray *arr = dx ? song[ADXSongDx] : song[ADXSongStd];
    if (![arr isKindOfClass:[NSArray class]]) return @[];
    return [arr sortedArrayUsingComparator:^NSComparisonResult(NSArray *a, NSArray *b) {
        NSInteger da = [a[0] integerValue], db = [b[0] integerValue];
        if (da == db) return NSOrderedSame;
        return da > db ? NSOrderedAscending : NSOrderedDescending;
    }];
}

@end
